:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --high: #e94560;
  --medium: #f5a623;
  --low: #4ecca3;
  --border: #0f3460;
  --focus: #ffd166;
  --radius: 8px;
  --pixel-border: 3px solid var(--border);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app {
  background: var(--card);
  border: var(--pixel-border);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--primary);
  text-shadow: 2px 2px 0 var(--border);
}

.task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 20px;
}

.input-group {
  flex: 1 1 160px;
  min-width: 0;
}

input[type="text"],
select {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  background: var(--bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="text"]:focus,
select:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.3);
}

input[type="text"]::placeholder {
  color: var(--text-muted);
}

.btn {
  padding: 10px 20px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  background: var(--bg);
  color: var(--text);
}

.btn:hover {
  background: var(--border);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(2px);
  box-shadow: none;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.btn.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.btn.primary:active {
  background: var(--primary);
}

.filters {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 6px 16px;
  font-size: 0.9375rem;
  font-family: inherit;
  background: var(--bg);
  color: var(--text-muted);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}

.filter-btn:hover {
  background: var(--border);
  color: var(--text);
}

.filter-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.filter-btn:active {
  transform: translateY(1px);
}

.filter-btn.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.filter-btn.active:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-left: 6px solid var(--border);
  border-radius: var(--radius);
  transition: border-color 0.2s, opacity 0.2s;
}

.task-item.priority-high {
  border-left-color: var(--high);
}

.task-item.priority-medium {
  border-left-color: var(--medium);
}

.task-item.priority-low {
  border-left-color: var(--low);
}

.task-item.completed {
  opacity: 0.6;
}

.task-item.completed .task-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.task-checkbox {
  width: 20px;
  height: 20px;
  min-width: 20px;
  cursor: pointer;
  accent-color: var(--primary);
}

.task-checkbox:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.task-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}

.priority-badge {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.priority-badge.high {
  background: var(--high);
  color: #fff;
}

.priority-badge.medium {
  background: var(--medium);
  color: #1a1a2e;
}

.priority-badge.low {
  background: var(--low);
  color: #1a1a2e;
}

.delete-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 1.25rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  line-height: 1;
  transition: color 0.2s, background 0.2s;
}

.delete-btn:hover {
  color: var(--primary);
  background: rgba(233, 69, 96, 0.15);
}

.delete-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.delete-btn:active {
  transform: scale(0.9);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 0;
  font-style: italic;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .app {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .task-form {
    flex-direction: column;
  }
  .btn.primary {
    width: 100%;
  }
  .task-item {
    flex-wrap: wrap;
    gap: 8px;
  }
  .priority-badge {
    order: 3;
  }
}

const taskForm = document.getElementById('task-form');
const taskInput = document.getElementById('task-input');
const prioritySelect = document.getElementById('priority-select');
const taskList = document.getElementById('task-list');
const emptyMessage = document.getElementById('empty-message');
const filterBtns = document.querySelectorAll('.filter-btn');

const PRIORITY_ORDER = { high: 0, medium: 1, low: 2 };

let tasks = [];
let currentFilter = 'all';

function loadTasks() {
  try {
    const stored = localStorage.getItem('pixel-todo-tasks');
    if (stored) {
      tasks = JSON.parse(stored);
    }
  } catch (e) {
    tasks = [];
  }
}

function saveTasks() {
  try {
    localStorage.setItem('pixel-todo-tasks', JSON.stringify(tasks));
  } catch (e) {
    // ignore storage errors
  }
}

function sortTasks() {
  tasks.sort((a, b) => {
    const pa = PRIORITY_ORDER[a.priority] ?? 3;
    const pb = PRIORITY_ORDER[b.priority] ?? 3;
    if (pa !== pb) return pa - pb;
    return a.id - b.id;
  });
}

function getFilteredTasks() {
  if (currentFilter === 'active') return tasks.filter(t => !t.completed);
  if (currentFilter === 'completed') return tasks.filter(t => t.completed);
  return tasks;
}

function render() {
  sortTasks();
  const filtered = getFilteredTasks();
  taskList.innerHTML = '';

  if (filtered.length === 0) {
    emptyMessage.hidden = false;
  } else {
    emptyMessage.hidden = true;
  }

  filtered.forEach(task => {
    const li = document.createElement('li');
    li.className = `task-item priority-${task.priority}${task.completed ? ' completed' : ''}`;
    li.dataset.id = task.id;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'task-checkbox';
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.completed ? 'incomplete' : 'complete'}`);
    checkbox.addEventListener('change', () => toggleTask(task.id));

    const span = document.createElement('span');
    span.className = 'task-text';
    span.textContent = task.text;

    const badge = document.createElement('span');
    badge.className = `priority-badge ${task.priority}`;
    badge.textContent = task.priority;

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.textContent = '\u00d7';
    delBtn.setAttribute('aria-label', `Delete task: ${task.text}`);
    delBtn.addEventListener('click', () => deleteTask(task.id));

    li.append(checkbox, span, badge, delBtn);
    taskList.appendChild(li);
  });
}

function addTask(text, priority) {
  const id = Date.now() + Math.random();
  tasks.push({ id, text, priority, completed: false });
  saveTasks();
  render();
}

function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (task) {
    task.completed = !task.completed;
    saveTasks();
    render();
  }
}

function deleteTask(id) {
  tasks = tasks.filter(t => t.id !== id);
  saveTasks();
  render();
}

function setFilter(filter) {
  currentFilter = filter;
  filterBtns.forEach(btn => {
    const isActive = btn.dataset.filter === filter;
    btn.classList.toggle('active', isActive);
    btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
  });
  render();
}

taskForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = taskInput.value.trim();
  if (!text) return;
  const priority = prioritySelect.value;
  addTask(text, priority);
  taskInput.value = '';
  taskInput.focus();
});

filterBtns.forEach(btn => {
  btn.addEventListener('click', () => setFilter(btn.dataset.filter));
});

loadTasks();
render();
